import{_ as e,o,c as s,a3 as n}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Manter descrição dos eventos à vista","description":"","frontmatter":{"title":"Manter descrição dos eventos à vista","id":"eproc-eventos-conteudo-visivel","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.9.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-eventos-conteudo-visivel"}]]},"headers":[],"relativePath":"funcionalidades/eproc-eventos-conteudo-visivel.md","filePath":"funcionalidades/eproc-eventos-conteudo-visivel.md"}'),t={name:"funcionalidades/eproc-eventos-conteudo-visivel.md"};function i(r,a,d,l,c,u){return o(),s("div",null,a[0]||(a[0]=[n('<h1 id="manter-descricao-dos-eventos-a-vista" tabindex="-1">Manter descrição dos eventos à vista <a class="header-anchor" href="#manter-descricao-dos-eventos-a-vista" aria-label="Permalink to &quot;Manter descrição dos eventos à vista&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Um evento com muitos documentos ocupa uma linha alta na tabela de eventos, e o eproc mostra a data, a descrição e o usuário no meio dessa linha. Quem vê só o começo ou só o fim da linha encontra apenas a lista de documentos. Este recurso leva essas informações para a parte da linha que está na tela.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, tabela de eventos.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><p>Não é preciso fazer nada. Role a tabela de eventos:</p><ul><li>quando só o começo de um evento está na tela, a data, a descrição e o usuário ficam no topo da linha;</li><li>quando o meio da linha está à vista, eles voltam ao meio, como o eproc mostra;</li><li>quando só o fim da linha está na tela, eles vão para baixo.</li></ul><p>A troca acontece quando a rolagem para por um instante, e não a cada movimento. Com as animações ligadas (aba Geral das configurações), o conteúdo desliza até o novo lugar.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Nas linhas que cabem inteiras na tela, nada muda.</li><li>Para voltar ao meio, o meio da linha precisa entrar um pouco na tela. Assim o conteúdo não fica indo e voltando quando a rolagem para bem em cima da borda.</li><li>A coluna de documentos fica como está.</li><li>Funciona também com o agrupamento de eventos ligado.</li></ul>',13)]))}const v=e(t,[["render",i]]);export{m as __pageData,v as default};
